<?php
namespace App\Livewire\Admin\Customers; use App\Models\Customer; use Livewire\Component;
class Edit extends Component{public Customer $customer;public string $name='';public string $email='';public string $phone='';public string $address='';public function mount():void{abort_unless(auth()->user()->isAdmin()||auth()->user()->hasPermission('customers.edit'),403);$this->name=$this->customer->name;$c=$this->customer->contact_info??[];foreach(['email','phone','address'] as $f)$this->$f=$c[$f]??'';}public function save(){$d=$this->validate(['name'=>['required','string','max:255'],'email'=>['nullable','email','max:255'],'phone'=>['nullable','string','max:255'],'address'=>['nullable','string','max:1000']]);$this->customer->update(['name'=>$d['name'],'contact_info'=>collect($d)->except('name')->filter(fn($v)=>filled($v))->all()]);session()->flash('success','Customer updated.');return $this->redirectRoute('admin.customers.show',$this->customer,navigate:true);}public function render(){return view('livewire.admin.customers.form',['heading'=>'Edit customer','submitLabel'=>'Save changes'])->layout('components.layouts.admin',['title'=>'Edit '.$this->customer->name]);}}
